    "sanskrit": "धर्मः प्रोज्झितकैतवोऽत्र परमो निर्मत्सराणां सतां\nवेद्यं वास्तवमत्र वस्तु शिवदं तापत्रयोन्मूलनम्।\nश्रीमद्भागवते महामुनिकृते किं वा परैरीश्वरः\nसद्यो हृद्यवरुध्यतेऽत्र कृतिभिः शुश्रूषुभिस्तत्क्षणात्॥२॥",
    "hindiTranslation": "इस श्रीमद्भागवत में कपट-रहित (मोक्ष की कामना से भी रहित निष्काम) परम धर्म का निरूपण है, जो मत्सर (ईर्ष्या)-रहित श्रेष्ठ संतों के लिए ग्राह्य है। इसमें वास्तविक सत्य जानने योग्य है जो परम कल्याणकारी और तीनों तापों (आधिभौतिक, आधिदैविक, आध्यात्मिक) का समूल नाश करने वाला है। महामुनि व्यास द्वारा रचित इस ग्रंथ के श्रवण की इच्छा मात्र से भगवान तत्क्षण साधक के हृदय में अवरुद्ध (प्रकट होकर स्थिर) हो जाते हैं।",
    "englishTranslation": "In this Srimad Bhagavatam is expounded the supreme Dharma completely purged of all selfish and deceptive motives, meant for saintly souls free from malice. Here the Absolute Reality is to be realized—reality that bestows ultimate welfare and uproots the threefold miseries. What need is there of any other scripture? By the noble who simply desire to hear it, the Supreme Lord is immediately captivated within their hearts.",
    "hinglishTranslation": "is shrimadbhagavat mein kapat-rahit (moksha ki kamana se bhi rahit nishkam) param dharma ka nirupan hai, jo matsar (eershya)-rahit shreshth snton ke lie grahy hai. isamen vastavik satya janane yogy hai jo param kalyanakari aur tinon tapon (aadhibhautik, aadhidaivik, aadhyatmik) ka samul nash karane vala hai. mahamuni vyas dvara rachit is grnth ke shravan ki ichchha matra se Bhagwan tatkshan sadhak ke hriday mein avaruddh (prakat hokar sthir) ho jate hain.",
