    "hindiTranslation": "हे भावुक और रसिक भक्तजनों! समस्त वेदों रूपी कल्पवृक्ष का यह पका हुआ अमृतमय फल श्रीमद्भागवत, श्रीशुकदेव जी के मुखारविंद से मिलकर और भी अधिक मधुर हो गया है। आप सब इस अमृत-रस का मोक्ष-पर्यंत निरंतर रसपान करते रहिए!",
    "englishTranslation": "O connoisseurs of divine nectar and devoted souls on earth! Drink constantly this ambrosial fruit of the Vedic wish-fulfilling tree, fallen from the mouth of Sri Sukadeva, enriched with the nectar of immortality; drink this Bhagavatam nectar till liberation and eternally beyond!",
