    "hindiTranslation": "जो शरणागतों के समस्त पापों को नष्ट करने वाला है, जो गऊओं के पीछे-पीछे वन-वन भटकता है, जो महालक्ष्मी का नित्य निवास-स्थल है और जिसने कालिया नाग के फनों पर नृत्य किया—उस पावन चरणकमल को हमारे हृदय पर स्थापित कर हमारे विरह-ताप को शांत कीजिए।",
    "englishTranslation": "Your lotus foot, which destroys the sins of surrendered souls, follows the grazing cows, is the eternal abode of Sri Lakshmi, and danced upon Kaliya's hoods—place that lotus foot upon our hearts and assuage our burning agony!",
