    "sanskrit": "तव कथामृतं तप्तजीवनं कविभिरीडितं कल्मषापहम्।\nश्रवणमङ्गलं श्रीमदाततं भुवि गृणन्ति ते भूरिदा जनाः॥९॥",
    "hindiTranslation": "आपकी अमृतमयी लीला-कथा संसारी तापों से तपे हुए जीवों को परम जीवन देने वाली है। बड़े-बड़े ब्रह्मज्ञानी संतों ने इसका गान किया है; यह समस्त पापों का समूल नाश करने वाली, सुनने मात्र से परम मंगल करने वाली और अनंत आध्यात्मिक ऐश्वर्य से परिपूर्ण है। इस धराधाम पर जो आपकी कथा का गान व विस्तार करते हैं, वे ही वास्तव में सबसे बड़े दानी हैं!",
    "englishTranslation": "The nectar of Your pastimes gives life unto those scorched by worldly miseries; it is celebrated by enlightened poets and washes away all sins. It is supremely auspicious to hear and bestows boundless spiritual wealth; those who distribute it upon this earth are verily the greatest benefactors!",
