    "hindiTranslation": "१. पृथ्वी, २. वायु, ३. आकाश, ४. जल, ५. अग्नि, ६. चंद्रमा, ७. सूर्य, ८. कबूतर, ९. अजगर, १०. समुद्र, ११. पतंगा, १२. भौंरा, १३. हाथी, १४. शहद निकालने वाला, १५. हिरण, १६. मछली, १७. पिंगला वेश्या, १८. कुरर पक्षी, १९. बालक, २०. कुमारी कन्या, २१. बाण बनाने वाला (शरकृत्), २२. सर्प, २३. मकड़ी (ऊर्णनाभि), और २४. भृंगी कीट (पेशकृत्)—ये मेरे चौबीस गुरु हैं।",
