    "hindiTranslation": "भगवान श्रीकृष्ण बोले—यह मानव शरीर समस्त आध्यात्मिक साधनों का मूल है, अत्यंत दुर्लभ होने पर भी प्रारब्धवश सुलभ हुआ है, और भवसागर तरने के लिए एक सुदृढ़ नौका के समान है। इसमें सद्गुरु कर्णधार (मल्लाह) हैं और मैं (ईश्वर) अनुकूल वायु के समान इसे आगे बढ़ा रहा हूँ; ऐसा अनुकूल अवसर पाकर भी जो मनुष्य भवसागर पार नहीं करता, वह वस्तुतः आत्मघाती है!",
    "englishTranslation": "Lord Krishna said: This human body is the primary and firm boat for crossing the ocean of worldly existence, extremely rare to attain yet obtained by grace, steered by a competent guru as helmsman, and propelled by Me as the favorable wind. A person who fails to cross the ocean with such aids is verily a slayer of his own soul!",
