    "hindiTranslation": "देवता बोले—हे शरणागतों के दुःख को दूर करने वाली देवि! हम पर प्रसन्न होइए। हे संपूर्ण जगत की माता! प्रसन्न होइए। हे विश्वेश्वरि! विश्व की रक्षा कीजिए; हे देवि! आप ही इस चराचर जगत की अधीश्वरी हैं।",
    "englishTranslation": "The Gods prayed: O Goddess who removes the distress of the surrendered, be pleased! Be gracious, O Mother of the entire universe! Be pleased, O Ruler of the cosmos, protect the world; You are the supreme Sovereign of all moving and unmoving creation.",
