    "hindiTranslation": "तर्क की कोई निश्चित प्रतिष्ठा नहीं है, श्रुतियां (वेद) भी विविध मार्ग बताती हैं, कोई एक ऐसा ऋषि नहीं जिसका मत सर्वमान्य हो; धर्म का परम तत्त्व तो हृदय-गुहा में अत्यंत गूढ़ छिपा है; इसलिए श्रेष्ठ महापुरुष (संत) जिस मार्ग से गए हैं, वही वास्तविक मार्ग है।",
    "englishTranslation": "Logic has no sure foundation; scriptures vary; there is no single sage whose word alone is authoritative. The truth of Dharma is concealed in the deep cave of the heart; therefore, that path alone is the true way which has been trodden by great souls.",
